CREATE DATABASE IF NOT EXISTS transeat_db CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
USE transeat_db;
CREATE TABLE IF NOT EXISTS admins(id INT AUTO_INCREMENT PRIMARY KEY,username VARCHAR(50) NOT NULL UNIQUE,password_hash VARCHAR(255) NOT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS drivers(id INT AUTO_INCREMENT PRIMARY KEY,driver_id VARCHAR(30) NOT NULL UNIQUE,driver_name VARCHAR(100) NOT NULL UNIQUE,plate_number VARCHAR(30) NOT NULL,is_archived TINYINT(1) NOT NULL DEFAULT 0,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,archived_at TIMESTAMP NULL);
CREATE TABLE IF NOT EXISTS departures(id INT AUTO_INCREMENT PRIMARY KEY,driver_pk INT NOT NULL,route_code ENUM('R1','R2') NOT NULL,from_location VARCHAR(50) NOT NULL,to_location VARCHAR(50) NOT NULL,departure_hour TINYINT NOT NULL,departure_period ENUM('AM','PM') NOT NULL,current_stop VARCHAR(120) NOT NULL,is_active TINYINT(1) NOT NULL DEFAULT 0,round_trips INT NOT NULL DEFAULT 0,departed_at DATETIME NULL,updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,CONSTRAINT fk_departure_driver FOREIGN KEY(driver_pk) REFERENCES drivers(id) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS earnings(id INT AUTO_INCREMENT PRIMARY KEY,driver_pk INT NOT NULL UNIQUE,total_earnings DECIMAL(10,2) NOT NULL DEFAULT 0.00,updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,CONSTRAINT fk_earnings_driver FOREIGN KEY(driver_pk) REFERENCES drivers(id) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS earning_transactions(id INT AUTO_INCREMENT PRIMARY KEY,driver_pk INT NOT NULL,transaction_type ENUM('EARNING','PENALTY') NOT NULL,amount DECIMAL(10,2) NOT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,CONSTRAINT fk_transaction_driver FOREIGN KEY(driver_pk) REFERENCES drivers(id) ON DELETE CASCADE);
